import React from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import Navbar from "./views/Navbar"; // Import the Navbar
import LoginView from "./views/LoginView";
import SignupView from "./views/SignupView";
import DashboardView from "./views/DashboardView";
import UsersView from "./views/UsersView";

function App() {
  const { currentUser } = useAuth(); // If using authentication

  return (
    <Router>
      {/* Navbar is placed **outside** <Routes> so it stays visible on all pages */}
      <Navbar />

      <Routes>
        {/* Public Routes */}
        <Route path="/login" element={!currentUser ? <LoginView /> : <Navigate to="/" />} />
        <Route path="/signup" element={!currentUser ? <SignupView /> : <Navigate to="/" />} />

        {/* Private Routes */}
        <Route path="/" element={currentUser ? <DashboardView /> : <Navigate to="/login" />} />
        <Route path="/dogs" element={currentUser ? <UsersView /> : <Navigate to="/login" />} />

        {/* Fallback */}
        <Route path="*" element={<Navigate to="/" />} />
      </Routes>
    </Router>
  );
}

export default App;
